// tsw.js: JavaScript port of the translationese-swe rule engine (tsw/).
//
// Data (rules, parameters, word lists, regexes) comes from ruleset.json,
// generated by web/build_ruleset.py from the Python objects. This file ports
// the code by hand: text normalisation with offset map, sentence splitter,
// tokenizer, Doc views, the rule types' maths (HitRule, RateRule,
// ChoiceRule, StatRule, LengthStat), the PredicateRules
// (connpunct.exclamation, wordorder.*) and the engine (family caps,
// annotate, describe). web/parity_test.ts checks it against Python.
//
// Offsets: Python counts code points, JavaScript counts UTF-16 units. This
// port works in UTF-16 units throughout (what the browser needs for
// highlighting); the parity test converts Python's offsets before comparing.
//
// Requires RegExp `v` flag support (Chrome/Edge 112+, Firefox 116+, Safari 17+, Deno).

const CAP_PREFIX = "cap:";

// ---------------------------------------------------------------------------
// small helpers

function clip(x, cap) {
  return x > cap ? cap : x < -cap ? -cap : x;
}

function side(x) {
  return x > 0 ? "TRANSLATED" : "ORIGINAL";
}

function cpLen(s) {
  let n = 0;
  for (const _ of s) n++;
  return n;
}

function inRanges(ranges, cp) {
  let lo = 0, hi = ranges.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const r = ranges[mid];
    if (cp < r[0]) hi = mid - 1;
    else if (cp > r[1]) lo = mid + 1;
    else return true;
  }
  return false;
}

// Python string comparison (code point order) for sorting labels
function cmpStr(a, b) {
  if (a === b) return 0;
  const A = [...a], B = [...b];
  const n = Math.min(A.length, B.length);
  for (let i = 0; i < n; i++) {
    const x = A[i].codePointAt(0), y = B[i].codePointAt(0);
    if (x !== y) return x < y ? -1 : 1;
  }
  return A.length < B.length ? -1 : A.length > B.length ? 1 : 0;
}

// --- Python %-formatting for the few specs the rules use -------------------

// x >= 0: decimal string with f digits, rounding exact ties to even like CPython
function fixedHalfEven(ax, f) {
  const s = ax.toFixed(f);
  if (ax < 1e-12 || ax >= 1e21) return s;
  const ex = ax.toFixed(100);
  const dot = ex.indexOf(".");
  const tail = ex.slice(dot + 1 + f);
  if (/^50*$/.test(tail)) {
    const trunc = f === 0 ? ex.slice(0, dot) : ex.slice(0, dot + 1 + f);
    const last = +trunc[trunc.length - 1];
    if (last % 2 === 0) return trunc;
  }
  return s;
}

function fmtF(x, prec, plus) {
  const neg = x < 0 || Object.is(x, -0);
  const s = fixedHalfEven(Math.abs(x), prec);
  return (neg ? "-" : plus ? "+" : "") + s;
}

function fmtG(x, prec, plus) {
  const p = prec === 0 ? 1 : prec;
  const neg = x < 0 || Object.is(x, -0);
  const sign = neg ? "-" : plus ? "+" : "";
  const ax = Math.abs(x);
  if (ax === 0) return sign + "0";
  if (!isFinite(ax)) return sign + (isNaN(ax) ? "nan" : "inf");
  const X = +ax.toExponential(p - 1).split("e")[1];
  if (X >= -4 && X < p) {
    let s = fixedHalfEven(ax, p - 1 - X);
    if (s.includes(".")) s = s.replace(/0+$/, "").replace(/\.$/, "");
    return sign + s;
  }
  let [m, e] = ax.toExponential(p - 1).split("e");
  if (m.includes(".")) m = m.replace(/0+$/, "").replace(/\.$/, "");
  const en = +e;
  return sign + m + "e" + (en < 0 ? "-" : "+") + String(Math.abs(en)).padStart(2, "0");
}

export function pyfmt(fmt, args) {
  let i = 0;
  return fmt.replace(/%(%|(\+?)(?:\.(\d+))?([sdfg]))/g, (all, pct, plus, prec, conv) => {
    if (pct === "%") return "%";
    const v = args[i++];
    if (conv === "s") return String(v);
    if (conv === "d") return String(Math.trunc(v));
    const pr = prec === undefined ? 6 : +prec;
    if (Number.isNaN(v)) return "nan";
    if (conv === "f") return fmtF(v, pr, !!plus);
    return fmtG(v, pr, !!plus);
  });
}

// ---------------------------------------------------------------------------
// engine factory

export function createEngine(RS) {
  const PH = RS.meta.placeholder;
  const T = RS.text;
  const rxCache = new Map();
  function rx(obj, flags) {
    const key = flags + "\u0000" + obj.js;
    let r = rxCache.get(key);
    if (!r) {
      r = new RegExp(obj.js, "v" + flags);
      rxCache.set(key, r);
    }
    return r;
  }

  // --- character predicates (Python str methods on one code point) ---------
  const RX_ALNUM = /^[\p{L}\p{N}]/v;
  const RX_ALPHA = /^\p{L}/v;
  const RX_UPPER = /^\p{Uppercase}/v;
  const RX_DEC = /^\p{Nd}/v;
  const isAlnumStart = (s) => RX_ALNUM.test(s);        // s[0].isalnum()
  const isAlphaCh = (ch) => RX_ALPHA.test(ch);
  const isUpperCh = (ch) => RX_UPPER.test(ch);
  const isDigitCp = (cp) => RX_DEC.test(String.fromCodePoint(cp)) || inRanges(T.digit_extra, cp);
  const isCombining = (cp) => inRanges(T.combining, cp);

  // --- normalisation ---------------------------------------------------------
  const TABLE = new Map(Object.entries(T.table));
  const isNFC = (s) => s === s.normalize("NFC");

  function normalise(text) {
    if (!isNFC(text)) text = text.normalize("NFC");
    let out = "";
    for (const ch of text) {
      const r = TABLE.get(ch);
      if (r === null) continue;
      out += r === undefined ? ch : r;
    }
    if (out.includes("  ")) out = out.replace(/ {2,}/g, " ");
    return out.replace(/^ +/, "").replace(/ +$/, "");
  }

  function normaliseWithMap(text) {
    const pieces = [];
    if (isNFC(text)) {
      let i = 0;
      for (const ch of text) {
        pieces.push([i, i + ch.length, ch]);
        i += ch.length;
      }
    } else {
      const cps = [...text];
      const pos = [];
      let u = 0;
      for (const c of cps) {
        pos.push(u);
        u += c.length;
      }
      pos.push(u);
      let i = 0;
      while (i < cps.length) {
        let j = i + 1;
        while (j < cps.length && isCombining(cps[j].codePointAt(0))) j++;
        pieces.push([pos[i], pos[j], cps.slice(i, j).join("").normalize("NFC")]);
        i = j;
      }
    }
    const out = [], starts = [], ends = [];
    for (const [s, e, chunk] of pieces) {
      for (const c of chunk) {
        const t = TABLE.get(c);
        if (t === null) continue;
        const r = t === undefined ? c : t;
        for (const rc of r) {
          if (rc === " " && (out.length === 0 || out[out.length - 1] === " ")) continue;
          out.push(rc);
          for (let k = 0; k < rc.length; k++) {
            starts.push(s);
            ends.push(e);
          }
        }
      }
    }
    while (out.length && out[out.length - 1] === " ") {
      out.pop();
      starts.pop();
      ends.pop();
    }
    return [out.join(""), starts, ends];
  }

  function lowerSameLength(text) {
    const low = text.toLowerCase();
    if (cpLen(low) === cpLen(text)) return low;
    let out = "";
    for (const c of text) {
      const l = c.toLowerCase();
      out += cpLen(l) === 1 ? l : c;
    }
    return out;
  }

  // --- sentence splitting ----------------------------------------------------
  const NO_SPLIT = new Set(T.no_split_abbr);
  const END_ABBR = new Set(T.end_abbr);
  const OPENERS = T.openers;

  function pyLower(s) {
    return s.toLowerCase();
  }

  function isAbbrevStop(text, pos) {
    const ws = pos > 0 ? text.lastIndexOf(" ", pos - 1) : -1;
    const word = text.slice(ws + 1, pos + 1).replace(/^[("'[]+/, "");
    const low = pyLower(word);
    if (NO_SPLIT.has(low)) return true;
    if (END_ABBR.has(low)) return false;
    const core = word.slice(0, -1);
    const coreCps = [...core];
    if (coreCps.length === 1 && isUpperCh(coreCps[0])) return true;
    if (core.includes(".")) {
      const parts = core.split(".");
      const stripped = [...core.replace(/\./g, "")];
      if (parts.every((p) => { const n = cpLen(p); return n > 0 && n <= 2; }) &&
          stripped.length > 0 && stripped.every(isAlphaCh)) return true;
    }
    return false;
  }

  function splitSentences(text) {
    const n = text.length;
    const cuts = [];
    const cand = rx(T.candidate, "g");
    cand.lastIndex = 0;
    let m;
    while ((m = cand.exec(text)) !== null) {
      const end = m.index + m[0].length;
      let j = end;
      while (j < n && OPENERS.includes(text[j])) j++;
      if (j >= n) continue;
      const cp = text.codePointAt(j);
      if (!(isUpperCh(String.fromCodePoint(cp)) || isDigitCp(cp))) continue;
      const punct = m[0];
      if (punct[0] === "." && punct.slice(0, 2) !== ".." && isAbbrevStop(text, m.index)) continue;
      cuts.push(end);
    }
    const hasAlnum = rx(T.has_alnum, "");
    const spans = [];
    let start = 0;
    for (const c of [...cuts, n]) {
      let s = start, e = c;
      while (s < e && text[s] === " ") s++;
      while (e > s && text[e - 1] === " ") e--;
      if (e > s) {
        if (hasAlnum.test(text.slice(s, e))) spans.push([s, e]);
        else if (spans.length) spans[spans.length - 1] = [spans[spans.length - 1][0], e];
      }
      start = c;
    }
    return spans;
  }

  // finditer(pattern, string, pos, endpos) semantics: lookbehind may see
  // before pos, nothing after endpos is visible
  function* finditer(re, s, pos = 0, endpos = s.length) {
    const sub = endpos === s.length ? s : s.slice(0, endpos);
    re.lastIndex = pos;
    let m;
    while ((m = re.exec(sub)) !== null) {
      yield m;
      if (m[0].length === 0) re.lastIndex++; // never happens: builder rejects empty-matching patterns
    }
  }

  // --- Doc -------------------------------------------------------------------
  class Doc {
    constructor(raw) {
      this.raw = typeof raw === "string" ? raw : String(raw);
      this._c = {};
    }
    _get(k, f) {
      if (!(k in this._c)) this._c[k] = f();
      return this._c[k];
    }
    get text() { return this._get("text", () => normalise(this.raw)); }
    get lower() { return this._get("lower", () => lowerSameLength(this.text)); }
    get _offsetMap() {
      return this._get("map", () => {
        const [norm, starts, ends] = normaliseWithMap(this.raw);
        if (norm !== this.text) throw new Error("normalise() and normaliseWithMap() disagree");
        return [starts, ends];
      });
    }
    toOrig(start, end) {
      const [starts, ends] = this._offsetMap;
      if (!starts.length) return [0, 0];
      if (end <= start) {
        const i = Math.min(start, starts.length - 1);
        return [starts[i], starts[i]];
      }
      return [starts[start], ends[Math.min(end, ends.length) - 1]];
    }
    get sent_spans() { return this._get("spans", () => splitSentences(this.text)); }
    get n_sentences() { return this.sent_spans.length; }
    get _tok() {
      return this._get("tok", () => {
        const t = this.text;
        const re = rx(T.token, "g");
        const allToks = [], allStarts = [], allWords = [];
        for (const [s, e] of this.sent_spans) {
          const toks = [], starts = [];
          for (const m of finditer(re, t, s, e)) {
            toks.push(m[0]);
            starts.push(m.index);
          }
          allToks.push(toks);
          allStarts.push(starts);
          allWords.push(toks.filter(isAlnumStart).map(pyLower));
        }
        return [allToks, allStarts, allWords];
      });
    }
    get sent_tokens() { return this._tok[0]; }
    get sent_tok_starts() { return this._tok[1]; }
    get sent_words() { return this._tok[2]; }
    get n_words() { return this._get("nw", () => this._tok[2].reduce((a, ws) => a + ws.length, 0)); }
    get is_address() {
      return this._get("addr", () => {
        const low = this.lower;
        const re = rx(T.address, "y");
        return this.sent_spans.map(([s, e]) => {
          re.lastIndex = s;
          return re.exec(low.slice(0, e)) !== null;
        });
      });
    }
  }

  // --- Matcher -----------------------------------------------------------------
  class Matcher {
    constructor(d) {
      this.re = rx(d.rx, "g");
      this.case = d.case;
      this.groups = d.groups || null;          // group -> label template (PH = surface)
      this.groupsRaw = d.groups_raw || null;   // group -> raw label
      this.key = (d.case ? "C" : "L") + d.rx.js;
    }
    target(doc) { return this.case ? doc.text : doc.lower; }
    // [[start, end, group or null]], cached per doc
    matches(doc) {
      const cache = doc._c.matches || (doc._c.matches = new Map());
      let out = cache.get(this.key);
      if (out) return out;
      out = [];
      for (const m of finditer(this.re, this.target(doc))) {
        let g = null;
        if (this.groups) {
          for (const name in this.groups) {
            if (m.groups && m.groups[name] !== undefined) { g = name; }
          }
        }
        out.push([m.index, m.index + m[0].length, g]);
      }
      cache.set(this.key, out);
      return out;
    }
    count(doc) { return this.matches(doc).length; }
  }

  function fmtLabel(tmpl, surface) {
    if (tmpl === null || tmpl === undefined) return "'" + surface + "'";
    return tmpl.split(PH).join(surface);
  }

  // --- rule types --------------------------------------------------------------
  class Rule {
    constructor(d) {
      Object.assign(this, d);
    }
    contribution(doc) {
      const raw = this._raw(doc);
      if (raw === 0) return 0;
      return clip(this.weight * raw, this.cap);
    }
    _scale(raw) {
      if (raw === 0) return [0, 0];
      const c = clip(this.weight * raw, this.cap);
      return [c, c / raw];
    }
    evidence(doc) { return [[], this.contribution(doc)]; }
    describe(doc, c) {
      return pyfmt("%s: %+.2f toward %s", [this.description, c, side(c)]);
    }
  }

  class HitRule extends Rule {
    constructor(d) {
      super(d);
      this.m = new Matcher(d.matcher);
      this.perLabel = d.per_label || null;
    }
    _matches(doc) {
      return this.m.matches(doc).map(([a, b, g]) => {
        const lab = g !== null && this.m.groups ? this.m.groups[g] : null;
        const v = this.perLabel !== null ? this.perLabel[g] : this.per_hit;
        return [a, b, lab, v];
      });
    }
    _raw(doc) {
      if (this.perLabel === null) return this.m.count(doc) * this.per_hit;
      let s = 0;
      for (const x of this._matches(doc)) s += x[3];
      return s;
    }
    evidence(doc) {
      const ms = this._matches(doc);
      if (!ms.length) return [[], 0];
      let sum = 0;
      for (const x of ms) sum += x[3];
      const [, s] = this._scale(sum);
      const t = doc.text;
      return [ms.map(([a, b, lab, v]) =>
        ({ start: a, end: b, share: s * v, label: fmtLabel(lab !== null ? lab : this.label, t.slice(a, b)) })), 0];
    }
    describe(doc, c) {
      const what = new Map();
      const t = doc.text;
      for (const [a, b, lab] of this._matches(doc)) {
        const k = fmtLabel(lab !== null ? lab : this.label, t.slice(a, b));
        what.set(k, (what.get(k) || 0) + 1);
      }
      const parts = [...what].map(([k, n]) => k + (n > 1 ? " x" + n : "")).join(", ");
      return pyfmt("%s: %s -> %+.2f toward %s", [this.description, parts || "no hits", c, side(c)]);
    }
  }

  class RateRule extends Rule {
    constructor(d) {
      super(d);
      this.m = new Matcher(d.matcher);
    }
    _raw(doc) {
      const n = doc.n_words;
      if (n === 0 || n < this.min_words) return 0;
      return this.m.count(doc) * this.log_ratio - n * this.per_word;
    }
    evidence(doc) {
      const n = doc.n_words;
      if (n === 0 || n < this.min_words) return [[], 0];
      const ms = this.m.matches(doc);
      const raw = ms.length * this.log_ratio - n * this.per_word;
      const [, s] = this._scale(raw);
      const t = doc.text;
      const hits = ms.map(([a, b, g]) => ({
        start: a, end: b, share: s * this.log_ratio,
        label: fmtLabel(g !== null && this.m.groups ? this.m.groups[g] : this.label, t.slice(a, b)),
      }));
      return [hits, s * (-n * this.per_word)];
    }
    describe(doc, c) {
      const n = doc.n_words, k = this.m.count(doc);
      return pyfmt("%s: %d hit%s in %d words (expected %.2g if original, %.2g if translated) -> %+.2f toward %s",
        [this.description, k, k === 1 ? "" : "s", n, n * this.rate_o / 1000, n * this.rate_t / 1000, c, side(c)]);
    }
  }

  class ChoiceRule extends Rule {
    constructor(d) {
      super(d);
      this.ma = new Matcher(d.matcher_a);
      this.mb = new Matcher(d.matcher_b);
    }
    _raw(doc) {
      const ka = this.ma.count(doc), kb = this.mb.count(doc);
      if (ka + kb === 0) return 0;
      return ka * this.la + kb * this.lb;
    }
    evidence(doc) {
      const A = this.ma.matches(doc), B = this.mb.matches(doc);
      if (!A.length && !B.length) return [[], 0];
      const [, s] = this._scale(A.length * this.la + B.length * this.lb);
      const t = doc.text;
      const lab = (m, g, dflt) => (g !== null && m.groupsRaw ? m.groupsRaw[g] : dflt);
      const hits = [
        ...A.map(([x, y, g]) => ({ start: x, end: y, share: s * this.la,
          label: lab(this.ma, g, this.label_a) + ": '" + t.slice(x, y) + "'" })),
        ...B.map(([x, y, g]) => ({ start: x, end: y, share: s * this.lb,
          label: lab(this.mb, g, this.label_b) + ": '" + t.slice(x, y) + "'" })),
      ];
      hits.sort((p, q) => p.start - q.start || p.end - q.end ||
        (p.share < q.share ? -1 : p.share > q.share ? 1 : 0) || cmpStr(p.label, q.label));
      return [hits, 0];
    }
    describe(doc, c) {
      const ka = this.ma.count(doc), kb = this.mb.count(doc);
      return pyfmt("%s: %s x%d vs %s x%d (share of %s: %.0f%% in originals, %.0f%% in translations) " +
        "-> %+.2f toward %s", [this.description, this.label_a, ka, this.label_b, kb, this.label_a,
        100 * this.p_o, 100 * this.p_t, c, side(c)]);
    }
  }

  // --- StatRule unit functions ---------------------------------------------------
  const ST = RS.predicates.stats;

  function sentenceLengths(doc) {
    const out = [], addr = doc.is_address, sw = doc.sent_words, sp = doc.sent_spans;
    for (let i = 0; i < sw.length; i++) {
      if (addr[i]) continue;
      if (sw[i].length) out.push([sw[i].length, sp[i]]);
    }
    return out;
  }

  function wordItems(doc) {
    return doc._get("stats_items", () => {
      const out = [], addr = doc.is_address, toks = doc.sent_tokens, starts = doc.sent_tok_starts;
      for (let si = 0; si < toks.length; si++) {
        if (addr[si]) continue;
        for (let k = 0; k < toks[si].length; k++) {
          const t = toks[si][k], s = starts[si][k];
          if (!isAlnumStart(t)) continue;
          const w = pyLower(t);
          if (w === ST.PLACEHOLDER || ![...w].some(isAlphaCh)) continue;
          out.push([w, s, s + t.length, si]);
        }
      }
      return out;
    });
  }

  const nLetters = (w) => [...w].filter(isAlphaCh).length;
  const isNominal = (w) => ST._NOMINAL_SUFFIXES.some((x) => w.endsWith(x)) && cpLen(w) > 7;

  const UNITS = {
    sentence_lengths: sentenceLengths,
    long_word_units(doc) {
      const spans = doc.sent_spans;
      return wordItems(doc).map(([w, , , si]) => [nLetters(w) > ST.LONG ? 1.0 : 0.0, spans[si]]);
    },
    av_nominal_units(doc) {
      const out = [];
      let prev = null;
      for (const it of wordItems(doc)) {
        const [w, s, e, si] = it;
        if (w === "av" && prev !== null && prev[3] === si && isNominal(prev[0])) out.push([1.0, [prev[1], e]]);
        else out.push([0.0, null]);
        prev = it;
      }
      return out;
    },
    av_other_units(doc) {
      const out = [];
      let prev = null;
      for (const it of wordItems(doc)) {
        const [w, s, e, si] = it;
        if (w === "av" && !(prev !== null && prev[3] === si && isNominal(prev[0]))) out.push([1.0, [s, e]]);
        else out.push([0.0, null]);
        prev = it;
      }
      return out;
    },
  };

  const gaussLogpdf = (x, mu, sd) => {
    const z = (x - mu) / sd;
    return -0.5 * z * z - Math.log(sd);
  };

  class StatRule extends Rule {
    _values(doc) {
      let vals = UNITS[this.units](doc);
      if (this.unit_clip) {
        const [lo, hi] = this.unit_clip;
        vals = vals.map(([v, sp]) => [Math.min(Math.max(v, lo), hi), sp]);
      }
      return vals;
    }
    _llr(x, n) {
      const r = Math.sqrt(n);
      return gaussLogpdf(x, this.mu_t, this.sd_t / r) - gaussLogpdf(x, this.mu_o, this.sd_o / r);
    }
    _mean(vals) {
      let s = 0;
      for (const [v] of vals) s += v;
      return s / vals.length;
    }
    _raw(doc) {
      const vals = this._values(doc), n = vals.length;
      if (n === 0 || n < this.min_units) return 0;
      return this._llr(this._mean(vals), n);
    }
    evidence(doc) {
      const vals = this._values(doc), n = vals.length;
      if (n === 0 || n < this.min_units) return [[], 0];
      const raw = this._llr(this._mean(vals), n);
      const [c, s] = this._scale(raw);
      const hits = [];
      let used = 0;
      for (const [v, sp] of vals) {
        const share = s * this._llr(v, 1);
        if (sp !== null && Math.abs(share) >= this.span_min) {
          hits.push({ start: sp[0], end: sp[1], share,
            label: pyfmt("%s %s = " + this.fmt, [this.unit_name, this.description, v]) });
          used += share;
        }
      }
      return [hits, c - used];
    }
    statistic(doc) {
      const vals = this._values(doc);
      return [vals.length ? this._mean(vals) : NaN, vals.length];
    }
    describe(doc, c) {
      const [x, n] = this.statistic(doc);
      return pyfmt("%s = " + this.fmt + " over %d %s%s (typical: " + this.fmt + " original, " + this.fmt +
        " translated) -> %+.2f toward %s", [this.description, x, n, this.unit_name, n === 1 ? "" : "s",
        this.mu_o, this.mu_t, c, side(c)]);
    }
  }

  class LengthStat extends StatRule {
    _var(n) { return this.sd_o * this.sd_o / n + this.tau * this.tau; }
    _slope(n) { return (this.mu_t - this.mu_o) / this._var(n); }
    _llr(x, n) { return this._slope(n) * (x - 0.5 * (this.mu_o + this.mu_t)); }
    evidence(doc) {
      const vals = this._values(doc), n = vals.length;
      if (n === 0 || n < this.min_units) return [[], 0];
      const raw = this._llr(this._mean(vals), n);
      const [c, s] = this._scale(raw);
      if (c === 0) return [[], 0];
      const per = s * this._slope(n) / n;
      const mid = 0.5 * (this.mu_o + this.mu_t);
      const groups = new Map();
      for (const [v, sp] of vals) {
        if (sp === null) continue;
        const k = sp[0] + "," + sp[1];
        groups.set(k, (groups.has(k) ? groups.get(k) : 0) + per * (v - mid));
      }
      const hits = [];
      let used = 0;
      for (const [k, share] of groups) {
        if (Math.abs(share) >= this.span_min) {
          const [a, b] = k.split(",").map(Number);
          hits.push({ start: a, end: b, share, label: this.unit_label || this.description });
          used += share;
        }
      }
      return [hits, c - used];
    }
    describe(doc, c) {
      const [x, n] = this.statistic(doc);
      if (n === 0 || n < this.min_units) {
        return pyfmt("%s: undefined (%d %ss) -> 0", [this.description, n, this.unit_name]);
      }
      return pyfmt("%s = " + this.fmt + " over %d %s%s (typical: " + this.fmt + " original, " + this.fmt +
        " translated) -> %+.2f toward %s", [this.description, x * this.scale, n, this.unit_name,
        n === 1 ? "" : "s", this.mu_o * this.scale, this.mu_t * this.scale, c, side(c)]);
    }
  }

  class PredicateRule extends Rule {
    constructor(d, impl) {
      super(d);
      this.impl = impl;
    }
    _raw(doc) { return this.impl.fn(doc) || 0; }
    evidence(doc) {
      const raw = this._raw(doc);
      const [c, s] = this._scale(raw);
      const hits = [];
      let used = 0;
      for (const [a, b, share, label] of this.impl.spans(doc)) {
        hits.push({ start: a, end: b, share: s * share, label });
        used += s * share;
      }
      return [hits, c - used];
    }
    describe(doc, c) {
      return this.impl.describe ? this.impl.describe(doc, c) : super.describe(doc, c);
    }
  }

  // --- connpunct.exclamation ---------------------------------------------------------
  const EX = RS.predicates.exclamation;
  function exclamations(doc) {
    const out = [], addr = doc.is_address, text = doc.text;
    const re = rx(EX.end_rx, "g");
    doc.sent_spans.forEach(([a, b], i) => {
      if (addr[i]) return;
      re.lastIndex = a;
      const m = re.exec(text.slice(0, b));
      if (m) out.push([m.index, m.index + 1]);
    });
    return out;
  }
  const exclamationImpl = {
    fn(doc) {
      const n = doc.n_words;
      if (n === 0) return 0;
      return exclamations(doc).length * EX.log - n * EX.per_word;
    },
    spans(doc) {
      return exclamations(doc).map(([a, b]) => [a, b, EX.log, EX.label]);
    },
  };

  // --- wordorder: clause-opening classifier ---------------------------------------------
  const W = RS.predicates.wordorder;
  const S = {};
  for (const k in W.sets) S[k] = new Set(W.sets[k]);
  const TS = {};
  for (const k in W.tuple_sets) TS[k] = new Set(W.tuple_sets[k]);
  const ADV_MULTI = W.seqs.ADV_MULTI, SUBJN_MULTI = W.seqs.SUBJN_MULTI;
  const rxMatch = (name, t) => {
    const re = rx(W.regex[name], "y");
    re.lastIndex = 0;
    return re.test(t);
  };
  const isWord = (tok) => tok.length > 0 && isAlnumStart(tok);
  const PUNCT4 = [",", "!", ".", ":"];

  function O(cat, a = 0, b = 0, fronted = "") {
    return { cat, a, b, fronted };
  }
  const OTHER = O("OTHER");

  function skipPrefix(toks, i) {
    const n = toks.length;
    while (i < n && !isWord(toks[i])) i++;
    for (let r = 0; r < 3; r++) {
      if (i < n && S._VOC_HEAD.has(toks[i])) {
        let j = i + 1;
        while (j < n && j <= i + 6 && !PUNCT4.includes(toks[j])) j++;
        if (j < n && toks[j] === ",") {
          i = j + 1;
          continue;
        }
      }
      break;
    }
    if (i + 1 < n && S._INTERJ.has(toks[i]) && (toks[i + 1] === "," || toks[i + 1] === "!")) i += 2;
    if (i < n && S._COORD.has(toks[i])) {
      i += 1;
      if (i < n && toks[i] === ",") i += 1;
    }
    return i;
  }

  function matchSeq(toks, i, seqs) {
    for (const s of seqs) {
      if (i + s.length > toks.length) continue;
      let ok = true;
      for (let k = 0; k < s.length; k++) if (toks[i + k] !== s[k]) { ok = false; break; }
      if (ok) return s.length;
    }
    return 0;
  }

  function npThenFin(toks, k, maxlen = 4) {
    const n = toks.length;
    if (k >= n) return -1;
    const t = toks[k];
    if (S.FIN.has(t) || S.SUBJ_PERS.has(t) || S._STOP.has(t) || S._COORD.has(t) || !isWord(t)) return -1;
    if (!S._NP_START.has(t) && (S._NOT_DEF.has(t) || !rxMatch("_DEF_SUFFIX", t))) return -1;
    for (let j = k + 1; j < Math.min(n, k + 1 + maxlen); j++) {
      const u = toks[j];
      if (!isWord(u) || S._STOP.has(u) || S.SUBJ_PERS.has(u) || S._COORD.has(u)) return -1;
      if (S.FIN.has(u)) return j;
    }
    return -1;
  }

  const finlike = (t) => S.FIN.has(t) || (!S._NONVERB.has(t) && rxMatch("_FIN_SUFFIX", t));
  const invEnd = (toks, k) => (k + 1 < toks.length && S.SUBJ_POST.has(toks[k + 1]) ? k + 2 : k + 1);
  const join = (toks, a, b) => toks.slice(a, b).join(" ");

  function afterPrefield(toks, p, j, kind, fronted, guessVerb = false) {
    const n = toks.length;
    let k = j;
    const comma = k < n && toks[k] === ",";
    if (comma) k += 1;
    if (k >= n) return null;
    const t = toks[k];
    if (S.FIN.has(t) || (guessVerb && !comma && finlike(t))) return O(kind, p, invEnd(toks, k), fronted);
    if (k + 1 < n && S.SUBJ_PERS.has(t) && S.FIN.has(toks[k + 1])) return O("NOINV", p, k + 2, fronted);
    if (kind === "INV_SUB" && comma && k + 1 < n && t === "så" && S.FIN.has(toks[k + 1])) {
      return O("SUB_SA", p, k + 2, fronted);
    }
    if (comma && kind !== "INV_SUB") {
      const v = npThenFin(toks, k);
      if (v > 0) return O("NOINV", p, v + 1, fronted);
    }
    return null;
  }

  function classifyOpening(toks) {
    const n = toks.length;
    if (n < 3 || toks.slice(-3).includes("?")) return OTHER;
    const p = skipPrefix(toks, 0);
    if (p >= n - 1) return OTHER;
    const t0 = toks[p], t1 = toks[p + 1];
    const t2 = p + 2 < n ? toks[p + 2] : "";

    if (S.SUBJ_PERS.has(t0)) {
      if (S.FIN.has(t1)) return O("S_PRON", p, p + 2);
      if (S.V3_ADV.has(t1) && S.FIN.has(t2)) return O("V3", p, p + 3);
      if (t0 !== "de") return OTHER;
    }

    if ((t0 === "det" || t0 === "den" || t0 === "de") && (t1 === "här" || t1 === "där") && S.FIN.has(t2)) {
      const t3 = p + 3 < n ? toks[p + 3] : "";
      if (S.SUBJ_PERS.has(t3) && !S.COPULA.has(t2)) return O("INV_OBJ", p, p + 4, t0 + " " + t1);
      return O("S_DEM", p, p + 3);
    }

    if (t0 === "det") {
      if (t1 === "är" || t1 === "var") {
        for (let j = p + 3; j < Math.min(n, p + 12); j++) {
          const u = toks[j];
          if (u === "som") return O("CLEFT", p, j + 1, "det " + t1);
          if (!isWord(u) || ["att", "när", "om", "eftersom", "då", "för"].includes(u)) break;
        }
      }
      if (S.FIN.has(t1)) {
        if (S.SUBJ_PERS.has(t2) && !S.COPULA.has(t1) && !["finns", "fanns", "gäller", "handlar"].includes(t1)) {
          return O("INV_OBJ", p, p + 3, "det");
        }
        return O("S_DET", p, p + 2);
      }
      return OTHER;
    }

    if (["detta", "denna", "dessa", "den", "denne"].includes(t0) && S.FIN.has(t1)) {
      if (S.SUBJ_PERS.has(t2) && !S.COPULA.has(t1)) return O("INV_OBJ", p, p + 3, t0);
      return O("S_DEM", p, p + 2);
    }

    if ((t0 === "så" || t0 === "sådant") && S.FIN.has(t1) && S.SUBJ_POST.has(t2)) return O("INV_OBJ", p, p + 3, t0);

    let m = matchSeq(toks, p, SUBJN_MULTI);
    let isSubjn = m > 0 || S.SUBJN1.has(t0);
    if (m === 0 && (t0 === "då" || t0 === "sedan" || t0 === "nu")) {
      if (S.FIN.has(t1)) return O("INV_ADV", p, invEnd(toks, p + 1), t0);
      isSubjn = t0 !== "nu" && S.SUBJ_POST.has(t1);
    }
    if (isSubjn) return classifySubclause(toks, p, p + (m || 1));

    m = matchSeq(toks, p, ADV_MULTI);
    if (m || S.ADV1.has(t0) || (!S.FIN.has(t0) && rxMatch("_ADV_SUFFIX", t0))) {
      const j = p + (m || 1);
      const guess = !TS._FOCUS_MULTI.has(join(toks, p, j)) && !S._FOCUS_ADV.has(t0);
      const r = afterPrefield(toks, p, j, "INV_ADV", join(toks, p, j), guess);
      if (r === null || (r.cat === "NOINV" && !m && S.ADV_NO_V2_CHECK.has(t0))) return OTHER;
      if (r.cat === "INV_ADV" && S.CONJ_ADV.has(r.fronted)) r.cat = "INV_CONJ";
      return r;
    }

    if (t0 === "vad" && S.SUBJ_POST.has(t1)) {
      for (let j = p + 2; j < Math.min(n, p + 12); j++) {
        if ([".", ";", ":", "!", "?"].includes(toks[j])) break;
        if (S.COPULA.has(toks[j]) && j > p + 2 && !S.SUBJ_POST.has(toks[j - 1])) return O("PSEUDO_CLEFT", p, j + 1, "vad");
      }
      return OTHER;
    }

    if (S.PREP.has(t0)) {
      if (t0 === "vad" && !["gäller", "beträffar", "angår"].includes(t1)) return OTHER;
      if (t0 === "för" && S.SUBJ_POST.has(t1)) return OTHER;
      let j = p + 1;
      while (j < n && j <= p + 10) {
        const t = toks[j];
        if (S._STOP.has(t) || [".", ";", ":", "!", "(", "–", '"'].includes(t)) return OTHER;
        if (j > p + 1) {
          if (S.FIN.has(t)) return O("INV_PP", p, invEnd(toks, j), join(toks, p, j));
          if (S.SUBJ_PERS.has(t)) {
            if (toks[j - 1] === "," && j + 1 < n && S.FIN.has(toks[j + 1])) return O("NOINV", p, j + 2, join(toks, p, j - 1));
            if (j <= p + 3 && j + 1 < n && S.FIN.has(toks[j + 1]) && !S.ADV_NO_V2_CHECK.has(toks[j - 1]) &&
                !toks.slice(p + 1, j).some((u) => S._NP_START.has(u) || !isWord(u))) {
              return O("NOINV", p, j + 2, join(toks, p, j));
            }
            return OTHER;
          }
          if (t === "," && j + 1 < n && S.FIN.has(toks[j + 1])) return O("INV_PP", p, invEnd(toks, j + 1), join(toks, p, j));
          if (t === "," && j <= p + 8) {
            const v = npThenFin(toks, j + 1);
            if (v > 0) return O("NOINV", p, v + 1, join(toks, p, j));
          }
        }
        j += 1;
      }
      return OTHER;
    }

    if (S.FIN.has(t0) || S._STOP.has(t0) || S._COORD.has(t0) || !isWord(t0)) return OTHER;
    let j = p + 1;
    while (j < n && j <= p + 5) {
      const t = toks[j];
      if (t === "," && j > p + 1) return OTHER;
      if (S.SUBJ_PERS.has(t) && j + 1 < n && finlike(toks[j + 1])) return contactRelative(toks, p, j);
      if (S._STOP.has(t) || !isWord(t) || S.SUBJ_PERS.has(t)) return OTHER;
      if (S.FIN.has(t)) {
        if (j + 1 < n && S.SUBJ_PERS.has(toks[j + 1]) && toks[j + 1] !== "de") return O("INV_NP", p, j + 2, join(toks, p, j));
        return O("S_NP", p, j + 1);
      }
      j += 1;
    }
    return OTHER;
  }

  function contactRelative(toks, p, j) {
    const n = toks.length;
    for (let k = j + 2; k < Math.min(n - 1, j + 14); k++) {
      const t = toks[k];
      if ([".", ";", ":", "!", "?", ",", "–"].includes(t) || S._STOP.has(t)) return OTHER;
      if (S.FIN.has(t) && S.SUBJ_PERS.has(toks[k + 1]) && toks[k + 1] !== "de" && !S.SUBJ_POST.has(toks[k - 1])) {
        return O("INV_NP", p, k + 2, join(toks, p, j));
      }
    }
    return OTHER;
  }

  function classifySubclause(toks, p, q) {
    const n = toks.length;
    const sub = join(toks, p, q);
    const fronted = sub;
    let infinitival = false;
    let ownFin;
    if (TS.SUBJN_WITH_VERB.has(sub)) {
      ownFin = q - 1;
    } else if (TS.SUBJN_INF.has(sub) && q < n && !S.SUBJ_POST.has(toks[q])) {
      ownFin = q;
      infinitival = true;
    } else if (q + 1 < n && S.SUBJ_POST.has(toks[q])) {
      ownFin = finlike(toks[q + 1]) || !S.V3_ADV.has(toks[q + 1]) ? q + 1 : q + 2;
    } else {
      ownFin = -1;
      for (let j = q; j < Math.min(n, q + 7); j++) {
        if (S.FIN.has(toks[j])) {
          ownFin = j;
          break;
        }
        if ([".", ";", ":", "!"].includes(toks[j])) return OTHER;
      }
      if (ownFin < 0) return OTHER;
    }
    let j = ownFin + 1;
    while (j < n && j <= p + 40) {
      const t = toks[j];
      if ([".", ";", ":", "!", "?"].includes(t)) return OTHER;
      if (t === ",") {
        const r = afterPrefield(toks, p, j, "INV_SUB", fronted);
        if (r !== null) return r;
      } else if (S.FIN.has(t) && j > ownFin + 1 && j + 1 < n && S.SUBJ_PERS.has(toks[j + 1]) &&
                 (infinitival || !S.SUBJ_POST.has(toks[j - 1])) && !S._STOP.has(toks[j - 1])) {
        return O("INV_SUB", p, j + 2, fronted);
      }
      j += 1;
    }
    return OTHER;
  }

  function openings(doc) {
    return doc._get("wo_openings", () => {
      const out = [], addr = doc.is_address;
      doc.sent_tokens.forEach((toks, i) => {
        if (addr[i]) return;
        out.push([i, classifyOpening(toks.map(pyLower))]);
      });
      return out;
    });
  }

  function tokSpan(doc, i, a, b) {
    const toks = doc.sent_tokens[i], starts = doc.sent_tok_starts[i];
    b = Math.min(b, toks.length);
    if (b <= a) b = a + 1;
    return [starts[a], starts[b - 1] + toks[b - 1].length];
  }

  function openingImpl(cats) {
    cats = new Set(cats);
    const alias = (c) => (c in W._OPEN_ALIAS ? W._OPEN_ALIAS[c] : c);
    const spans = (doc) => {
      const out = [];
      for (const [i, o] of openings(doc)) {
        const c = alias(o.cat);
        if (!cats.has(c)) continue;
        const [a, b] = tokSpan(doc, i, o.a, o.b);
        out.push([a, b, W.OPENING_LLR[c], W._OPEN_LABEL[c]]);
      }
      return out;
    };
    return {
      spans,
      fn(doc) {
        let s = 0;
        for (const x of spans(doc)) s += x[2];
        return s;
      },
      describe(doc, c) {
        const cnt = new Map();
        for (const [, o] of openings(doc)) {
          const k = alias(o.cat);
          if (cats.has(k)) cnt.set(k, (cnt.get(k) || 0) + 1);
        }
        const top = [...cnt].sort((x, y) => y[1] - x[1]).slice(0, 4)
          .map(([k, v]) => W._OPEN_LABEL[k] + " " + v).join(", ");
        return pyfmt("sentence openings (%s): %+.2f toward %s", [top, c, side(c)]);
      },
    };
  }

  const v2Impl = {
    spans(doc) {
      const out = [];
      for (const [i, o] of openings(doc)) {
        if (o.cat === "NOINV" || o.cat === "V3") {
          const [a, b] = tokSpan(doc, i, o.a, o.b);
          out.push([a, b, W.V2_VIOLATION_HIT[o.cat], W._V2_LABEL[o.cat]]);
        }
      }
      for (const m of finditer(rx(W.regex.EMBEDDED_NEG_RX, "g"), doc.lower)) {
        out.push([m.index, m.index + m[0].length, W.V2_VIOLATION_HIT.EMB, W._V2_LABEL.EMB]);
      }
      return out;
    },
    fn(doc) {
      let s = 0;
      for (const x of this.spans(doc)) s += x[2];
      return s;
    },
  };

  const PREDICATES = {
    "connpunct.exclamation": exclamationImpl,
    "wordorder.fronted_theme": openingImpl(W.FRONTED_THEME),
    "wordorder.subject_theme": openingImpl(W.SUBJECT_THEME),
    "wordorder.v2_violation": v2Impl,
  };

  // --- build rules -----------------------------------------------------------------------
  const KINDS = { hit: HitRule, rate: RateRule, choice: ChoiceRule, stat: StatRule, lengthstat: LengthStat };
  const rules = RS.rules.map((d) => {
    if (d.kind === "predicate") {
      const impl = PREDICATES[d.name];
      if (!impl) throw new Error("no JS port of predicate rule " + d.name);
      return new PredicateRule(d, impl);
    }
    const K = KINDS[d.kind];
    if (!K) throw new Error("unknown rule kind " + d.kind);
    return new K(d);
  });
  const ruleByName = new Map(rules.map((r) => [r.name, r]));
  const famCap = new Map(RS.families.map((f) => [f.name, f.cap]));
  const byFamily = new Map();
  for (const r of rules) {
    if (!byFamily.has(r.family)) byFamily.set(r.family, []);
    byFamily.get(r.family).push(r);
  }

  function run(doc) {
    let total = RS.prior;
    const contrib = new Map(), fam = new Map();
    for (const [f, rs] of byFamily) {
      let s = 0;
      for (const r of rs) {
        const c = r.contribution(doc);
        if (c) {
          contrib.set(r.name, c);
          s += c;
        }
      }
      const cs = clip(s, famCap.get(f));
      fam.set(f, [s, cs]);
      total += cs;
    }
    return [total, contrib, fam];
  }

  const logistic = (x) => 1 / (1 + Math.exp(-Math.max(-50, Math.min(50, x))));

  function explainSpans(doc) {
    const spans = [];
    for (const r of rules) {
      const [hits] = r.evidence(doc);
      for (const h of hits) {
        if (!h.share) continue;
        const [a, b] = doc.toOrig(h.start, h.end);
        spans.push({ start: a, end: b, text: doc.raw.slice(a, b), rule: r.name, family: r.family,
          direction: h.share > 0 ? "T" : "O", contribution_share: h.share, label: h.label });
      }
    }
    spans.sort((x, y) => x.start - y.start || x.end - y.end || cmpStr(x.rule, y.rule));
    return spans;
  }

  function annotate(text, top = 5) {
    const doc = new Doc(text);
    const [total, contrib, fam] = run(doc);
    const docLevel = [];
    for (const r of rules) {
      if (!contrib.has(r.name)) continue;
      const [, resid] = r.evidence(doc);
      if (Math.abs(resid) > 1e-9) {
        docLevel.push({ rule: r.name, family: r.family, direction: resid > 0 ? "T" : "O",
          contribution: resid, label: r.describe(doc, contrib.get(r.name)) });
      }
    }
    for (const [f, [s, cs]] of fam) {
      if (cs !== s) {
        docLevel.push({ rule: CAP_PREFIX + f, family: f, direction: cs - s > 0 ? "T" : "O",
          contribution: cs - s, label: pyfmt("family '%s' capped at %+.2f (raw sum %+.2f)", [f, cs, s]) });
      }
    }
    const items = [...contrib].sort((x, y) => Math.abs(y[1]) - Math.abs(x[1]));
    const families = {};
    for (const [f, [s, cs]] of fam) families[f] = { raw: s, clipped: cs };
    const evidence = items.map(([n, c]) => {
      const r = ruleByName.get(n);
      return { rule: n, family: r.family, kind: r.kind, contribution: c, description: r.description,
        describe: r.describe(doc, c) };
    });
    return {
      score: total, prob: logistic(total), label: total > 0 ? "translated" : "original",
      n_words: doc.n_words, n_sentences: doc.n_sentences,
      rules: Object.fromEntries(contrib), families,
      spans: explainSpans(doc), doc_level: docLevel,
      evidence_translated: evidence.filter((e) => e.contribution > 0).slice(0, top).map((e) => e.describe),
      evidence_original: evidence.filter((e) => e.contribution < 0).slice(0, top).map((e) => e.describe),
      evidence, // all fired rules with their human-readable description (web page)
    };
  }

  function score(text) {
    return run(new Doc(text))[0];
  }

  return {
    annotate, score, rules, Doc, families: RS.families,
    // for tests
    _internal: { normalise, normaliseWithMap, lowerSameLength, splitSentences, rx, finditer, classifyOpening,
      isAlnumStart, isAlphaCh, isUpperCh, isDigitCp, isCombining },
  };
}
